import type { Cli } from './apps'
import { CLIS } from './clis'
import { isAbsolute, posix, resolvePath } from './tree'

export type Invocation = { head: string; args: string[]; cwd: string }
export type CliCall = { cli: Cli; args: string[]; cwd: string }

const SEPARATORS = new Set(['&&', '||', ';', '|', '&', '\n', '(', ')', '`'])
const PREFIXES = new Set(['do', 'then', 'else', 'elif', 'if', '!', 'time', '{', 'env', 'command', 'builtin', 'exec', 'nohup', 'sudo', 'nice', 'xargs', 'timeout', 'while', 'until'])
const PREFIX_VALUED: Record<string, Set<string>> = {
  sudo: new Set(['-u', '-g', '-C', '-h', '-p', '-U', '-r', '-t', '-D']),
  timeout: new Set(['-k', '-s', '--kill-after', '--signal']),
  xargs: new Set(['-n', '-I', '-P', '-L', '-s', '-d', '-E', '-a']),
  env: new Set(['-u', '-C', '-S', '--unset', '--chdir']),
  nice: new Set(['-n']),
  exec: new Set(['-a']),
}
const RUNNERS: Record<string, string[]> = { npx: [], bunx: [], pnpx: [], bun: ['x'], npm: ['exec', 'x'], pnpm: ['dlx', 'exec'], yarn: ['dlx', 'exec'] }
const MAX_CALLS = 50
const REDIRECT = /^(\d*>>?|\d*<|\d*>&\d*|&>>?)$/

export function tokenize(command: string): string[] {
  const out: string[] = []
  let cur = ''
  let quote = ''
  let has = false
  for (let i = 0; i < command.length; i++) {
    const ch = command[i] ?? ''
    if (!quote && ch === '#' && !has && !cur) {
      while (i + 1 < command.length && command[i + 1] !== '\n') i++
      continue
    }
    if (quote) {
      if (ch === quote) quote = ''
      else if (ch === '\\' && quote === '"' && i + 1 < command.length) cur += command[++i] ?? ''
      else cur += ch
      continue
    }
    if (ch === '"' || ch === "'") {
      quote = ch
      has = true
    } else if (ch === '\\' && i + 1 < command.length) {
      cur += command[++i] ?? ''
      has = true
    } else if (ch === '\n') {
      if (has || cur) out.push(cur)
      cur = ''
      has = false
      out.push('\n')
    } else if (/\s/.test(ch)) {
      if (has || cur) out.push(cur)
      cur = ''
      has = false
    } else if (ch === '>' || ch === '<') {
      let op = /^\d+$/.test(cur) || (cur === '&' && !has) ? cur : ''
      if (!op && (has || cur)) out.push(cur)
      op += ch
      while (command[i + 1] === '>' || command[i + 1] === '&' || /\d/.test(command[i + 1] ?? '')) {
        if (command[i + 1] === '&' && op.endsWith('&')) break
        op += command[++i]
      }
      out.push(op)
      cur = ''
      has = false
    } else if (ch === '(' || ch === ')' || ch === '`') {
      if (has || cur) out.push(cur)
      cur = ''
      has = false
      out.push(ch)
    } else if (ch === ';' || ch === '|' || ch === '&') {
      if (ch === '&' && command[i + 1] === '>') {
        if (has || cur) out.push(cur)
        cur = '&'
        has = false
        continue
      }
      if (has || cur) out.push(cur)
      cur = ''
      has = false
      const two = command.slice(i, i + 2)
      if (two === '&&' || two === '||') {
        out.push(two)
        i++
      } else out.push(ch)
    } else {
      cur += ch
      has = true
    }
  }
  if (has || cur) out.push(cur)
  if (!quote) return out
  return command
    .split(/(&&|\|\||[;|\n])/)
    .flatMap(part => (/^(&&|\|\||[;|\n])$/.test(part) ? [part] : part.trim().split(/\s+/).filter(Boolean)))
}

function operators(line: string): { word: string; tabs: boolean; expand: boolean }[] {
  const found: { word: string; tabs: boolean; expand: boolean }[] = []
  const outer: boolean[] = []
  let single = false
  let double = false
  for (let i = 0; i < line.length; i++) {
    const ch = line[i]
    if (single) {
      if (ch === "'") single = false
      continue
    }
    if (ch === '\\') {
      i++
      continue
    }
    if (ch === '$' && line[i + 1] === '(') {
      outer.push(double)
      double = false
      i++
      continue
    }
    if (ch === ')' && outer.length && !double) {
      double = outer.pop() ?? false
      continue
    }
    if (ch === '"') {
      double = !double
      continue
    }
    if (double) continue
    if (ch === "'") {
      single = true
      continue
    }
    if (ch === '#' && (i === 0 || /\s/.test(line[i - 1] ?? ''))) break
    if (ch === '<' && line[i + 1] === '<' && line[i + 2] !== '<') {
      const m = line.slice(i).match(/^<<(-?)\s*(['"]?)([A-Za-z_][A-Za-z0-9_]*)\2/)
      if (m) {
        found.push({ word: m[3] ?? '', tabs: m[1] === '-', expand: !m[2] })
        i += m[0].length - 1
      }
    }
  }
  return found
}

function heredocless(command: string): string {
  const out: string[] = []
  const pending: { word: string; tabs: boolean; expand: boolean }[] = []
  for (const line of command.split('\n')) {
    const head = pending[0]
    if (head) {
      if ((head.tabs ? line.replace(/^\t+/, '') : line) === head.word) pending.shift()
      else if (head.expand) out.push(...substitutions(line))
      continue
    }
    out.push(line)
    pending.push(...operators(line))
  }
  return out.join('\n')
}

function substitutions(command: string): string[] {
  const out: string[] = []
  let single = false
  let double = false
  for (let i = 0; i < command.length; i++) {
    const ch = command[i]
    if (single) {
      if (ch === "'") single = false
      continue
    }
    if (ch === '\\') {
      i++
      continue
    }
    if (ch === "'" && !double) {
      single = true
      continue
    }
    if (ch === '"') {
      double = !double
      continue
    }
    if (ch === '#' && !double && (i === 0 || /\s/.test(command[i - 1] ?? ''))) {
      while (i + 1 < command.length && command[i + 1] !== '\n') i++
      continue
    }
    if (ch === '$' && command[i + 1] === '(') {
      let depth = 0
      for (let j = i + 1; j < command.length; j++) {
        if (command[j] === '(') depth++
        else if (command[j] === ')' && --depth === 0) {
          out.push(command.slice(i + 2, j))
          i = j
          break
        }
      }
      continue
    }
    if (ch === '`') {
      let j = i + 1
      while (j < command.length && command[j] !== '`') j += command[j] === '\\' ? 2 : 1
      if (j < command.length) out.push(command.slice(i + 1, j))
      i = j
    }
  }
  return out
}

function skipFlags(toks: string[], j: number, word: string): number {
  const valued = PREFIX_VALUED[word]
  while (j < toks.length && (toks[j] ?? '').startsWith('-') && !SEPARATORS.has(toks[j] ?? '')) j += valued?.has(toks[j] ?? '') ? 2 : 1
  return j
}

export function cdTo(cwd: string, dir: string, home: string): string {
  if (dir === '~' || dir.startsWith('~/')) return home && isAbsolute(home) ? resolvePath(home, dir.slice(2)) : ''
  if (dir === '-' || /[~$`]/.test(dir)) return ''
  if (isAbsolute(posix(dir))) return resolvePath('/', dir)
  return cwd && isAbsolute(cwd) && !/[~$`]/.test(cwd) ? resolvePath(cwd, dir) : ''
}

export function invocations(command: string, sessionCwd: string, home: string, wanted: (head: string) => boolean): Invocation[] {
  const text = heredocless(command)
  const toks = tokenize(text)
  const found: Invocation[] = []
  let cwd = sessionCwd
  let start = true
  for (let i = 0; i < toks.length && found.length < MAX_CALLS; i++) {
    const t = toks[i] ?? ''
    if (SEPARATORS.has(t)) {
      start = true
      continue
    }
    if (!start) continue
    start = false
    let j = i
    for (;;) {
      const tok = toks[j] ?? ''
      const word = tok.split('/').pop() ?? ''
      if (/^[A-Za-z_][A-Za-z0-9_]*=/.test(tok)) j++
      else if (word === 'timeout') {
        j = skipFlags(toks, j + 1, word)
        if (/^\d/.test(toks[j] ?? '')) j++
      } else if (word === 'command' && /^-[A-Za-z]*[vV]/.test(toks[j + 1] ?? '')) break
      else if (PREFIXES.has(word)) j = skipFlags(toks, j + 1, word)
      else break
    }
    const head = toks[j]?.split('/').pop() ?? ''
    const next = toks[j + 1]
    if (head === 'cd') {
      cwd = next === undefined || SEPARATORS.has(next) ? cdTo(cwd, '~', home) : cdTo(cwd, next, home)
      continue
    }
    if (!head || !wanted(head)) continue
    const args: string[] = []
    let k = j + 1
    while (k < toks.length && !SEPARATORS.has(toks[k] ?? '')) {
      const tok = toks[k++] ?? ''
      if (REDIRECT.test(tok)) {
        if (!/&\d*$/.test(tok) || tok.startsWith('&')) k++
        continue
      }
      args.push(tok)
    }
    found.push({ head, args, cwd })
    i = k - 1
  }
  const keyOf = (inv: Invocation) => [inv.head, ...inv.args].join('\0')
  const seen = new Set(found.map(keyOf))
  for (const body of substitutions(text)) {
    for (const inv of invocations(body, cwd, home, wanted)) {
      const key = keyOf(inv)
      if (seen.has(key) || found.length >= MAX_CALLS) continue
      seen.add(key)
      found.push(inv)
    }
  }
  return found
}

export function cliCalls(command: string, cwd: string, home: string): CliCall[] {
  const names = new Set(CLIS.flatMap(c => c.commands))
  const out: CliCall[] = []
  for (const inv of invocations(command, cwd, home, head => names.has(head) || head in RUNNERS)) {
    let head = inv.head
    let args = inv.args
    const subs = RUNNERS[head]
    if (subs && !names.has(head)) {
      let k = subs.length === 0 ? 0 : subs.includes(args[0] ?? '') ? 1 : -1
      if (k < 0) continue
      while (k < args.length && (args[k] ?? '').startsWith('-')) k++
      head = (args[k] ?? '').replace(/(.)@[^/]*$/, '$1')
      args = args.slice(k + 1)
    }
    const cli = CLIS.find(c => c.commands.includes(head) || c.packages.includes(head))
    if (cli) out.push({ cli, args, cwd: inv.cwd })
  }
  return out
}

function asksHelp(call: CliCall): boolean {
  return call.args.some(a => a === '--help' || a === '-h')
}

export function mutates(call: CliCall): boolean {
  const verb = call.args.find(a => !a.startsWith('-'))
  return !asksHelp(call) && verb !== undefined && call.cli.mutating.includes(verb)
}

export function deploys(call: CliCall): boolean {
  return !asksHelp(call) && call.args.filter(a => !a.startsWith('-')).slice(0, 2).some(a => call.cli.deploy.includes(a))
}

files.hooks/tree.ts:
import type { FileNode, FileTree, Theme } from '../types'
import { stronger } from './icons'

export type Entry = { name: string; kind: 'file' | 'dir' | 'other'; mtimeMs: number; isLink: boolean }
export type Row = { node: FileNode; depth: number; open: boolean }

const collator = new Intl.Collator(undefined, { numeric: true, sensitivity: 'base' })

export const DEFAULT_THEME: Theme = {
  fg: '',
  accent: '#5b9bd5',
  muted: '#808a96',
  urgent: '#d0605e',
  selection: '#3e4451',
}

export function emptyTree(root: string): FileTree {
  return {
    root,
    nodes: [],
    expanded: [],
    cursor: '',
    selected: '',
    query: '',
    showHidden: true,
    git: {},
    ignored: [],
    untrackedDirs: [],
    diff: {},
    counts: {},
    status: '',
    flash: [],
    flashDim: [],
    flashOn: false,
    flashTones: {},
    scroll: null,
    top: '',
    work: null,
  }
}

export function parseTheme(toml: string): Theme {
  const get = (k: string) => toml.match(new RegExp(`^${k}\\s*=\\s*"(#[0-9a-fA-F]{6})"`, 'm'))?.[1]
  return {
    fg: get('foreground') ?? get('color7') ?? DEFAULT_THEME.fg,
    accent: get('accent') ?? get('color4') ?? DEFAULT_THEME.accent,
    muted: get('muted') ?? get('color8') ?? DEFAULT_THEME.muted,
    urgent: get('red') ?? get('color1') ?? DEFAULT_THEME.urgent,
    selection: get('selection') ?? DEFAULT_THEME.selection,
  }
}

export function join(dir: string, name: string): string {
  return dir.endsWith('/') ? dir + name : `${dir}/${name}`
}

let drives = false

export function dirname(path: string): string {
  if (drives && /^[A-Za-z]:\/[^/]*$/.test(path)) return path.slice(0, 3)
  const i = path.lastIndexOf('/')
  return i <= 0 ? '/' : path.slice(0, i)
}

export function useDrives(on: boolean): void {
  drives = on
}

export function posix(path: string): string {
  if (!drives) return path
  return path.replace(/\\/g, '/').replace(/^\/([A-Za-z])(\/|$)/, (_, d: string) => `${d.toUpperCase()}:/`)
}

export function isAbsolute(path: string): boolean {
  return path.startsWith('/') || (drives && /^[A-Za-z]:\//.test(path))
}

export function resolvePath(base: string, path: string): string {
  const p = posix(path)
  const abs = isAbsolute(p) ? p : join(base, p)
  const head = (drives ? abs.match(/^[A-Za-z]:\//)?.[0] : undefined) ?? '/'
  const parts: string[] = []
  for (const seg of abs.slice(head.length).split('/')) {
    if (seg === '' || seg === '.') continue
    if (seg === '..') parts.pop()
    else parts.push(seg)
  }
  return head + parts.join('/')
}

export function toNodes(dir: string, list: Entry[]): FileNode[] {
  return list
    .map(e => ({
      id: join(dir, e.name),
      parent: dir,
      name: e.name,
      kind: e.isLink ? ('link' as const) : e.kind === 'dir' ? ('dir' as const) : ('file' as const),
      hidden: e.name.startsWith('.'),
      mtime: e.mtimeMs,
      loaded: false,
    }))
    .sort((a, b) => (a.kind === 'dir' ? 0 : 1) - (b.kind === 'dir' ? 0 : 1) || collator.compare(a.name, b.name))
}

function under(id: string, set: Set<string>): boolean {
  for (let i = id.lastIndexOf('/'); i > 0; i = id.lastIndexOf('/', i - 1)) if (set.has(id.slice(0, i))) return true
  return false
}

export function replaceChildren(nodes: FileNode[], listed: Map<string, FileNode[]>): FileNode[] {
  if (listed.size === 0) return nodes
  const keep = new Map<string, FileNode>()
  for (const n of nodes) if (listed.has(n.parent)) keep.set(n.id, n)
  const fresh: FileNode[] = []
  for (const kids of listed.values())
    for (const k of kids) {
      const old = keep.get(k.id)
      fresh.push(old && old.kind === 'dir' && k.kind === 'dir' ? { ...k, loaded: old.loaded } : k)
    }
  const freshIds = new Set(fresh.map(k => k.id))
  const gone = new Set([...keep.keys()].filter(id => !freshIds.has(id)))
  const out: FileNode[] = []
  for (const n of nodes) {
    if (listed.has(n.parent) || (gone.size > 0 && under(n.id, gone))) continue
    out.push(listed.has(n.id) ? { ...n, loaded: true } : n)
  }
  const taken = new Set(out.map(n => n.id))
  return [...out, ...fresh.filter(k => !taken.has(k.id) && !(gone.size > 0 && under(k.id, gone)))]
}

export async function mapLimit<T, R>(items: T[], limit: number, fn: (item: T) => Promise<R>): Promise<R[]> {
  const out: R[] = new Array(items.length)
  let next = 0
  const worker = async () => {
    while (next < items.length) {
      const i = next++
      out[i] = await fn(items[i] as T)
    }
  }
  await Promise.all(Array.from({ length: Math.min(limit, items.length) }, worker))
  return out
}

export type GitStatus = {
  git: Record<string, string>
  ignored: string[]
  untrackedDirs: string[]
  files: Record<string, Change>
}

export type Change = 'new' | 'mod' | 'del'

export function mapper(root: string, prefix: string): (rel: string) => string | null {
  return rel => (rel.startsWith(prefix) ? join(root, rel.slice(prefix.length).replace(/\/$/, '')).replace(/\/$/, '') : null)
}

export function parseGit(stdout: string, root: string, prefix: string): GitStatus {
  const map = mapper(root, prefix)
  const git: Record<string, string> = {}
  const ignored: string[] = []
  const untrackedDirs: string[] = []
  const files: Record<string, Change> = {}
  const parts = stdout.split('\0')
  for (let i = 0; i < parts.length; i++) {
    const rec = parts[i] ?? ''
    if (rec.length < 4) continue
    const xy = rec.slice(0, 2)
    const raw = rec.slice(3)
    if (xy[0] === 'R' || xy[0] === 'C') i++
    const path = map(raw)
    if (!path) continue
    if (xy === '!!') {
      ignored.push(path)
      continue
    }
    if (xy === '??' && raw.endsWith('/')) untrackedDirs.push(path)
    else files[path] = xy === '??' || (xy.includes('A') && !xy.includes('D')) ? 'new' : xy.includes('D') && !/U/.test(xy) ? 'del' : 'mod'
    const letter =
      xy === '??'
        ? '?'
        : /U/.test(xy) || xy === 'AA' || xy === 'DD'
          ? 'U'
          : (['D', 'M', 'R', 'C', 'A', 'T'].find(c => xy.includes(c)) ?? '')
    if (!letter) continue
    git[path] = stronger(git[path], letter)
    let dir = dirname(path)
    while (dir.length >= root.length && dir !== '/') {
      git[dir] = stronger(git[dir], letter)
      if (dir === root) break
      dir = dirname(dir)
    }
  }
  return { git, ignored, untrackedDirs, files }
}

export function parseNumstat(stdout: string, root: string, prefix: string, into: Record<string, [number, number]>): void {
  const map = mapper(root, prefix)
  const parts = stdout.split('\0')
  for (let i = 0; i < parts.length; i++) {
    const rec = parts[i] ?? ''
    if (!rec) continue
    const m = rec.match(/^(-|\d+)\t(-|\d+)\t(.*)$/s)
    if (!m) continue
    let path = m[3] ?? ''
    if (path === '') {
      i += 2
      path = parts[i] ?? ''
    }
    if (!path) continue
    const add = m[1] === '-' ? 0 : Number(m[1])
    const del = m[2] === '-' ? 0 : Number(m[2])
    const abs = map(path)
    if (!abs) continue
    const prev = into[abs] ?? [0, 0]
    into[abs] = [prev[0] + add, prev[1] + del]
  }
}

export function rollUp(diff: Record<string, [number, number]>, root: string): Record<string, [number, number]> {
  const out: Record<string, [number, number]> = { ...diff }
  for (const [path, [add, del]] of Object.entries(diff)) {
    let dir = dirname(path)
    while (dir.length >= root.length && dir !== '/') {
      const prev = out[dir] ?? [0, 0]
      out[dir] = [prev[0] + add, prev[1] + del]
      if (dir === root) break
      dir = dirname(dir)
    }
  }
  return out
}

export function rollCounts(files: Record<string, Change>, root: string): Record<string, [number, number, number]> {
  const out: Record<string, [number, number, number]> = {}
  const slot = { new: 0, mod: 1, del: 2 } as const
  for (const [path, change] of Object.entries(files)) {
    let dir = dirname(path)
    while (dir.length >= root.length && dir !== '/') {
      const cur = out[dir] ?? [0, 0, 0]
      cur[slot[change]] += 1
      out[dir] = cur
      if (dir === root) break
      dir = dirname(dir)
    }
  }
  return out
}

export function underAny(id: string, set: Set<string>, root: string): boolean {
  if (set.size === 0) return false
  let cur = id
  while (cur.length >= root.length) {
    if (set.has(cur)) return true
    const up = dirname(cur)
    if (up === cur) break
    cur = up
  }
  return false
}

export function inside(root: string, path: string): boolean {
  return path === root || path.startsWith(root.endsWith('/') ? root : `${root}/`)
}

export function ancestorsOf(id: string, root: string): string[] {
  const out: string[] = []
  if (!root) return out
  for (let dir = dirname(id), prev = id; dir !== prev && dir !== root && inside(root, dir); prev = dir, dir = dirname(dir)) out.push(dir)
  return out
}

export function visibleRows(t: FileTree, top = ''): Row[] {
  const kids = new Map<string, FileNode[]>()
  for (const n of t.nodes) {
    if (!t.showHidden && n.hidden) continue
    const list = kids.get(n.parent)
    if (list) list.push(n)
    else kids.set(n.parent, [n])
  }
  const q = t.query.trim().toLowerCase()
  let keep: Set<string> | null = null
  if (q) {
    keep = new Set()
    for (const n of t.nodes) {
      if (!n.name.toLowerCase().includes(q)) continue
      keep.add(n.id)
      for (const a of ancestorsOf(n.id, t.root)) keep.add(a)
    }
  }
  const open = new Set(t.expanded)
  const rows: Row[] = []
  const walk = (dir: string, depth: number) => {
    for (const n of kids.get(dir) ?? []) {
      if (keep && !keep.has(n.id)) continue
      const isOpen = n.kind === 'dir' && (keep ? kids.has(n.id) : open.has(n.id))
      rows.push({ node: n, depth, open: isOpen })
      if (isOpen) walk(n.id, depth + 1)
    }
  }
  walk(top || t.root, 0)
  return rows
}

export function stamp(ms: number): string {
  if (!ms) return ''
  const d = new Date(ms)
  const p = (v: number) => String(v).padStart(2, '0')
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())} ${p(d.getHours())}:${p(d.getMinutes())}`
}

